{
  "Core Conclusion": {
    "claim": "docker compose 默认 restart 策略会在容器退出后尝试重启，但这并不等于『总是重启失败容器』，因此『后端自愈』结论的置信度上限为启发式层。",
    "confidence_cap": "medium-low"
  },
  "Epistemic Breakdown": [
    {
      "layer": "L0/Axiom",
      "statement": "docker compose restart 策略仅在容器进程退出时触发重启；若配置为 restart: always 或 restart: unless-stopped，则重启会持续发生。",
      "certainty": "axiomatic",
      "note": "这是 Docker 官方文档和 compose 规范中定义的行为，不依赖环境观察。"
    },
    {
      "layer": "L1/Observed Evidence",
      "statement": "观测到：当后端容器因崩溃退出且未手动停止时，docker compose 会将其重新拉起。",
      "certainty": "observed under stated conditions",
      "evidence": "restart 策略的运行时行为，可通过 `docker compose ps` 和容器启动时间戳验证。适用条件：daemon 正常运行、容器未进入 paused/stopped 状态、未执行 `docker compose stop`。"
    },
    {
      "layer": "L2/Heuristic",
      "statement": "『失败容器总会被重启，所以后端自愈』是一个有用但不完备的启发式。",
      "certainty": "heuristic",
      "applicability": "适用于崩溃/退出码非零/进程被杀等瞬时故障；不适用于：端口冲突、资源耗尽、配置错误、无限崩溃重启循环、依赖服务未就绪。",
      "counterexamples": [
        "容器反复崩溃并触发 restart: always，但应用因数据库连接失败始终无法启动，重启不等于恢复。",
        "restart 策略上限（如 restart: on-failure:3 或 Docker 默认的 backoff 指数退避）可能导致容器最终不再重启。"
      ]
    },
    {
      "layer": "L3/Conclusion",
      "statement": "『docker compose 总是重启失败容器，所以后端自愈』的置信度不能高于启发式层。",
      "confidence_cap": "medium-low",
      "reason": "结论依赖 L2 启发式作为最弱依据层，L0 和 L1 仅支持『重启发生』，不支持『自愈达成』。"
    }
  ],
  "Evidence Gaps": [
    {
      "gap": "未说明 compose 文件中的具体 restart 策略（always / unless-stopped / on-failure / no）。",
      "required_evidence": "提供 compose 配置中 restart 字段的实际值。",
      "impact": "若为 restart: no，L1 观测不成立，结论失效。"
    },
    {
      "gap": "未区分『进程重启』与『业务自愈』：重启后应用可能仍处于不可用状态。",
      "required_evidence": "健康检查通过、请求成功率恢复、错误日志停止等业务层指标。",
      "impact": "若缺少业务恢复证据，L3 结论的置信度应降为 low。"
    },
    {
      "gap": "未覆盖 Docker daemon 自身故障、宿主机重启、网络分区等场景。",
      "required_evidence": "跨主机或守护进程级故障恢复测试记录。",
      "impact": "在更大故障域内，『总是重启』断言不成立。"
    }
  ],
  "Full Repair Plan": {
    "defect": "原表述把『重启策略』宣称提升为『总是重启 + 自愈』，缺少策略类型、恢复判据、适用域和反例。",
    "fix": {
      "change_points": [
        "将『always restarts』改为『在 restart: always / unless-stopped 配置下会重启退出容器』。",
        "将『self-healing』限定为『进程级重启恢复，不保证业务可用性』。",
        "在结论中标注启发式性质及置信度上限。"
      ],
      "migration_impact": "文档与监控告警口径需同步更新；若已有『后端自愈』的 SLO 承诺，需重新评估其依赖基础。",
      "rollback_path": "保留原表述所在版本，可随时 git revert；监控口径改动通过配置项开关切换。",
      "falsifiable_acceptance_criteria": [
        "构造一个持续崩溃的容器并配置 restart: always，观察重启是否在指数退避后停止——若停止，则原『总是重启』断言被证伪。",
        "让容器在缺少数据库时启动但无法服务，验证业务健康检查失败——若失败，则『自愈』断言被证伪。",
        "在 CI 中固定运行上述两个反例测试，结果通过才允许合并涉及自愈表述的变更。"
      ]
    }
  }
}
